{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <meta name="description" content="About page for a wellness coaching practice focused on habits, frameworks and steady progress.">
  <style>
    :root{--bg:#fff;--accent:#6b7cff;--muted:#64748b;--card:#f6f8ff;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.4;color:#0f172a;background:linear-gradient(180deg,#fbfdff 0%,#f7fbff 100%);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent;position:sticky;top:0;z-index:40}
    .brand{font-weight:700;letter-spacing:0.2px}
    nav a{margin-left:18px;color:#0f172a;text-decoration:none;font-weight:600}
    .nav-row{display:flex;align-items:center}

    /* Split diagonal hero */
    .hero{display:grid;grid-template-columns:1fr 1fr;min-height:56vh;align-items:center;gap:0;overflow:hidden}
    .hero-left{padding:64px 56px 48px}
    .title{font-size:clamp(28px,4.4vw,44px);margin:0 0 12px}
    .lede{color:var(--muted);margin:0 0 18px}
    .cta-row{display:flex;gap:14px}
    .btn{background:var(--accent);color:#fff;padding:12px 16px;border-radius:8px;border:0;font-weight:700;cursor:pointer}
    .btn.secondary{background:transparent;color:var(--accent);border:2px solid rgba(107,124,255,0.12)}

    .hero-right{position:relative;min-height:320px;display:flex;align-items:center;justify-content:center}
    .diagonal{position:absolute;inset:0;background:linear-gradient(135deg,#eef2ff 0%,#eaf5ff 60%);clip-path:polygon(10% 0,100% 0,100% 100%,0% 100%);display:flex;align-items:center;justify-content:center}
    .pattern{width:88%;height:88%;background-image:url('assets/img/pattern.svg');background-size:280px;background-repeat:repeat;opacity:0.95}

    main{padding:36px 56px}
    .grid{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:start}
    .card{background:var(--card);padding:18px;border-radius:12px}

    /* Reveal animation */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms ease,transform 520ms cubic-bezier(.2,.9,.3,1)}
    .reveal.visible{opacity:1;transform:none}

    .gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
    .gallery .tile{background:linear-gradient(180deg,#fff 0%,#f8fbff 100%);padding:28px;border-radius:10px}

    footer{padding:28px 56px;color:var(--muted);font-size:14px}

    /* Modal styles */
    .modal-backdrop{position:fixed;inset:0;background:rgba(4,6,12,0.5);display:none;align-items:center;justify-content:center;z-index:80}
    .modal{background:#fff;padding:22px;border-radius:12px;max-width:720px;width:92%;box-shadow:0 20px 50px rgba(12,18,36,0.15)}
    .modal .controls{display:flex;gap:8px;margin-top:12px}
    .mode-btn{padding:8px 12px;border-radius:8px;border:1px solid #e6eefc;background:transparent;cursor:pointer}
    .close-btn{background:transparent;border:0;cursor:pointer;font-size:18px}

    @media (max-width:880px){
      .hero{grid-template-columns:1fr;min-height:60vh}
      .hero-right{order:-1;min-height:200px}
      .grid{grid-template-columns:1fr}
      nav a{display:none}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <div class="nav-row">
      <nav>
        <a href="index.html">Start</a>
        <a href="about.html">Why</a>
        <a href="services.html">Work</a>
        <a href="programs.html">Plans</a>
        <a href="pricing.html">Rates</a>
        <a href="testimonials.html">Stories</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <section class="hero">
    <div class="hero-left">
      <h1 class="title">A practical path to steadier days and clearer focus</h1>
      <p class="lede">We design habits, rhythms and simple frameworks that fit into busy schedules — so people make measurable shifts without overwhelm.</p>
      <div class="cta-row">
        <button class="btn" id="primaryCta">{{PRIMARY_CTA_LABEL}}</button>
        <button class="btn secondary" id="tryNow">Try it now</button>
      </div>
    </div>
    <div class="hero-right">
      <div class="diagonal">
        <div class="pattern" aria-hidden="true"></div>
      </div>
    </div>
  </section>

  <main>
    <div class="grid">
      <section>
        <h2 class="reveal">How I work</h2>
        <p class="reveal">I combine practical routines, short accountability check-ins and an adaptable framework so you and I can build a repeatable path toward your priority outcomes: clearer energy rhythms, steadier focus, and daily practices that stick.</p>

        <div class="card reveal" style="margin-top:18px">
          <h3>What to expect</h3>
          <ul>
            <li>Clear priorities and tiny, trackable habits that matter.</li>
            <li>A flexible structure you can use as seasons change.</li>
            <li>Tools to measure progress without extra friction.</li>
          </ul>
        </div>

        <div class="card reveal" style="margin-top:18px">
          <h3>Common questions</h3>
          <p><strong>Will this replace healthcare?</strong> No. This coaching focuses on routines, behaviors and practical supports—not medical treatment.</p>
          <p><strong>How long until I see change?</strong> Clients typically notice shifts in daily energy and focus within 2–6 weeks when they practice the small routines we design together.</p>
        </div>
      </section>

      <aside>
        <div class="card reveal">
          <h4>Snapshot</h4>
          <p><strong>Offer:</strong> VIP Day & ongoing containers
          <br><strong>Location:</strong> {{CITY}}, {{STATE}}</p>
          <p style="margin-top:8px"><a href="{{PRIMARY_CTA_URL}}" class="btn" style="display:inline-block">Book a conversation</a></p>
        </div>

        <div class="card reveal" style="margin-top:16px">
          <h4>Contact</h4>
          <p>{{EMAIL}}<br>{{PHONE}}</p>
        </div>
      </aside>
    </div>

    <section style="margin-top:34px">
      <h3 class="reveal">Examples from the field</h3>
      <div class="gallery">
        <div class="tile reveal">A simple morning pulse to plan the day</div>
        <div class="tile reveal">An evening micro-review to close the loop</div>
        <div class="tile reveal">A 60-minute VIP rhythm reset for busy leaders</div>
      </div>
    </section>

    <section style="margin-top:34px">
      <div class="card reveal">
        <h3>Ready for a focused conversation?</h3>
        <p>We often start with a short exploratory session to map priorities and a 1-page plan you can use immediately.</p>
        <div style="margin-top:12px"><a href="{{PRIMARY_CTA_URL}}" class="btn">Start your plan</a></div>
      </div>
    </section>
  </main>

  <footer>
    <div>© <span id="year"></span> {{BUSINESS_NAME}} — Intentional coaching for daily practices. <span style="float:right">{{CITY}}, {{STATE}}</span></div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="modal" class="modal-backdrop" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal" role="document">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <strong id="modalTitle">Try a quick practice</strong>
        <button class="close-btn" id="closeModal" aria-label="Close modal">✕</button>
      </div>

      <p id="modalIntro">Choose a brief guided exercise to reset attention or jot a quick reflection.</p>

      <div class="controls" style="margin-top:12px">
        <button class="mode-btn" data-mode="breath">Breathing (1m)</button>
        <button class="mode-btn" data-mode="journal">Journaling (3 prompts)</button>
        <button class="mode-btn" data-mode="intention">Set an intention</button>
      </div>

      <div id="modalBody" style="margin-top:14px"></div>
    </div>
  </div>

  <script>
    // Simple helpers
    document.getElementById('year').textContent = new Date().getFullYear();

    // Primary CTA navigation
    document.getElementById('primaryCta').addEventListener('click', function(){
      location.href = '{{PRIMARY_CTA_URL}}';
    });

    // Modal logic
    const modal = document.getElementById('modal');
    const modalBody = document.getElementById('modalBody');
    const modalTitle = document.getElementById('modalTitle');
    const intro = document.getElementById('modalIntro');
    document.getElementById('tryNow').addEventListener('click', openModal);
    document.getElementById('closeModal').addEventListener('click', closeModal);
    modal.addEventListener('click', (e)=>{ if(e.target===modal) closeModal(); });
    document.addEventListener('keydown', (e)=>{ if(e.key==='Escape') closeModal(); });

    function openModal(){
      modal.style.display='flex';
      modal.setAttribute('aria-hidden','false');
      intro.textContent = 'Choose a brief guided exercise to reset attention or jot a quick reflection.';
      modalBody.innerHTML='';
    }
    function closeModal(){
      modal.style.display='none';
      modal.setAttribute('aria-hidden','true');
      stopTimers();
    }

    // Timers
    let timers=[];
    function stopTimers(){ timers.forEach(t=>clearInterval(t)); timers=[]; }

    // Mode buttons
    document.querySelectorAll('.mode-btn').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const mode = btn.getAttribute('data-mode');
        startMode(mode);
      });
    });

    function startMode(mode){
      stopTimers();
      modalBody.innerHTML='';
      if(mode==='breath') startBreathing();
      if(mode==='journal') startJournaling();
      if(mode==='intention') startIntention();
    }

    // Breathing: 4-4-6 cycle for 60s
    function startBreathing(){
      modalTitle.textContent='Guided breathing — one minute';
      const display = document.createElement('div');
      display.style.fontSize='22px';
      display.style.padding='12px 0';
      modalBody.appendChild(display);

      let cycles = 0; let totalCycles=6; // roughly 1 minute
      function cycle(){
        display.textContent = 'Inhale — 4';
        let t=4; let id = setInterval(()=>{ t--; if(t>=0) display.textContent = 'Inhale — '+(t+1); if(t<=0){ clearInterval(id);
          display.textContent='Hold — 4';
          let h=4; let hid=setInterval(()=>{ h--; display.textContent='Hold — '+(h+1); if(h<=0){ clearInterval(hid);
            display.textContent='Exhale — 6';
            let e=6; let eid=setInterval(()=>{ e--; display.textContent='Exhale — '+(e+1); if(e<=0){ clearInterval(eid); cycles++; if(cycles<totalCycles) cycle(); else finish(); } },1000); } },1000);
        } },1000);
        timers.push(id);
      }
      function finish(){ display.textContent='Nice — take a slow breath and return when ready.'; }
      cycle();
    }

    // Journaling: three quick prompts with timer and a textarea
    function startJournaling(){
      modalTitle.textContent='Focused journaling — 3 prompts';
      const prompts = [
        'What one small win can I create today?',
        'What feels draining or unnecessary to stop?',
        'One practical next step I can take in the next 24 hours?'
      ];
      const container = document.createElement('div');
      const textarea = document.createElement('textarea');
      textarea.rows=6; textarea.style.width='100%'; textarea.style.marginTop='8px'; textarea.placeholder='Write freely...';
      container.appendChild(textarea);
      const promptBox = document.createElement('div');
      promptBox.style.marginTop='8px'; promptBox.style.fontWeight='600'; container.insertBefore(promptBox, textarea);
      modalBody.appendChild(container);

      let i=0; function nextPrompt(){
        if(i>=prompts.length){ promptBox.textContent='Done — save or close.'; return; }
        promptBox.textContent = prompts[i];
        let countdown=45; promptBox.textContent += '  ('+countdown+'s)';
        let id=setInterval(()=>{ countdown--; if(countdown>=0) promptBox.textContent = prompts[i]+'  ('+countdown+'s)'; if(countdown<=0){ clearInterval(id); i++; nextPrompt(); } },1000);
        timers.push(id);
      }
      nextPrompt();
    }

    // Intention: short guided prompt and save to localStorage
    function startIntention(){
      modalTitle.textContent='Set an intention';
      const form = document.createElement('div');
      const input = document.createElement('input'); input.style.width='100%'; input.placeholder='A short intention for today (e.g., "Finish one key task before noon")';
      input.style.padding='10px'; input.style.borderRadius='8px'; input.style.border='1px solid #e6eefc';
      const save = document.createElement('button'); save.className='btn'; save.textContent='Save intention'; save.style.marginTop='10px';
      form.appendChild(input); form.appendChild(save);
      const saved = document.createElement('div'); saved.style.marginTop='10px'; form.appendChild(saved);
      modalBody.appendChild(form);
      save.addEventListener('click', ()=>{
        const val = input.value.trim(); if(!val) return; localStorage.setItem('today_intention', val); saved.textContent='Saved — you can close this modal. Intentions are stored only in your browser.';
      });
      const existing = localStorage.getItem('today_intention'); if(existing){ saved.textContent='Previous intention: '+existing; }
    }

    // Scroll reveal with prefers-reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduced){ items.forEach(it=>it.classList.add('visible')); return; }
      const io = new IntersectionObserver((entries, obs)=>{
        entries.forEach(ent=>{
          if(ent.isIntersecting){ ent.target.classList.add('visible'); obs.unobserve(ent.target); }
        });
      },{threshold:0.08});
      items.forEach(it=>io.observe(it));
    })();
  </script>
</body>
</html>"} 
